    "keyTooltip": {
      "sourceKey": "Spell_QiyanaQv2_Tooltip",
      "text": "如果奇亚娜并未拥有一个<keywordMajor>附魔</keywordMajor>，那么她会进行斩击，对小范围内的敌人们造成<physicalDamage>@VanillaDamage@物理伤害</physicalDamage>。如果她已有一个<keywordMajor>附魔</keywordMajor>，那么这个技能会获得额外距离并基于<keywordMajor>附魔</keywordMajor>类型获得一个额外效果：<li><keywordMajor>寒冰附魔</keywordMajor>：暂时<status>禁锢</status>，然后是持续@SlowDuration@秒的@SlowPotency*-100@%<status>减速</status>。<li><keywordMajor>岩石附魔</keywordMajor>：对低于@CritThreshold*100@%生命值的敌人们造成额外的<physicalDamage>@TremorDamage@物理伤害</physicalDamage>。<li><keywordMajor>荒野附魔</keywordMajor>：留下一条小径，来使奇亚娜<keywordStealth>隐形</keywordStealth>并提供<speed>@Haste*100@%移动速度</speed>。<br>"
    },
    "keyCost": {
      "sourceKey": "Spell_Default_Cost",
      "text": "@Cost@ @AbilityResourceName@"
    },
    "keySummary": {
      "sourceKey": "Spell_QiyanaQ_Summary",
      "text": "奇亚娜挥舞她的武器，造成伤害和基于她元素的额外效果。"
    },
    "keyTooltipExtendedBelowLine": {
      "sourceKey": "Spell_QiyanaQ_TooltipExtendedBelowLine",
      "text": "<rules>第一个之后的敌人转而受到<physicalDamage>@FalloffDamage@物理伤害</physicalDamage>。<br>这个技能对野怪造成@JungleDamageAmp*100@%伤害。<br>{{Reminder_Invisibility}}</rules>"
    }
  }
