  "currentTexts": {
    "keyName": {
      "sourceKey": "Spell_YunaraQ_Name",
      "text": "灵蕴拳"
    },
    "keySummary": {
      "sourceKey": "Spell_YunaraQ_Summary",
      "text": "芸阿娜获得攻击速度、额外附带伤害并且她的攻击会散播至附近的敌人。"
    },
    "keyTooltip": {
      "sourceKey": "Spell_YunaraQ_Tooltip",
      "text": "<spellPassive>被动</spellPassive>：芸阿娜造成<magicDamage>@Calc_Passive_Damage@魔法伤害</magicDamage><OnHit>%i:OnHit%攻击特效</OnHit>并且攻击提供<evolve>@Resource_Nonchampion@灵蕴</evolve> (对抗英雄时为<evolve>@Resource_Champion@灵蕴</evolve>)。<br><br><spellPassive>主动</spellPassive>：芸阿娜消耗<evolve>@Resource_Max@灵蕴</evolve>，在@Buff_Duration@秒期间里获得<attackSpeed>@Calc_Attack_Speed@攻击速度</attackSpeed>并且造成额外<magicDamage>@Calc_Damage@魔法伤害</magicDamage><OnHit>%i:OnHit%攻击特效</OnHit>。在此期间，她的攻击会散播至附近的敌人，对其造成<physicalDamage>@Calc_Damage_Spread@物理伤害</physicalDamage>。<br><br><keywordMajor>超凡形态</keywordMajor>：这个技能会即刻激活并持续@Spell.YunaraR:Buff_Duration@秒。"
    },
    "keyTooltipExtended": {
      "sourceKey": "Spell_YunaraQ_TooltipExtended",
      "text": "<spellPassive>被动</spellPassive>：芸阿娜的攻击造成额外的<magicDamage>@Calc_Passive_Damage@魔法伤害</magicDamage><OnHit>%i:OnHit%攻击特效</OnHit>。打出一次攻击时提供<evolve>@Resource_Nonchampion@灵蕴</evolve>。(攻击英雄时为<evolve>@Resource_Champion@灵蕴</evolve>)，持续@Resource_Duration@秒。(最大值：<evolve>@Resource_Max@灵蕴</evolve>)。在停止普攻@Resource_Duration@秒后会导致芸阿娜每@Resource_Loss_Interval@秒损失<evolve>@Resource_Loss@灵蕴</evolve>。<br><br><spellPassive>主动</spellPassive>：芸阿娜消耗<evolve>@Resource_Max@灵蕴</evolve>，在@Buff_Duration@秒期间里获得<attackSpeed>@Calc_Attack_Speed@攻击速度</attackSpeed>并且造成额外<magicDamage>@Calc_Damage@魔法伤害</magicDamage><OnHit>%i:OnHit%攻击特效</OnHit>。在此期间，她的攻击会散播至附近的敌人，对其造成<physicalDamage>@Calc_Damage_Spread@物理伤害</physicalDamage>。<br><br><keywordMajor>超凡形态</keywordMajor>：这个技能会即刻激活并持续@Spell.YunaraR:Buff_Duration@秒。"
    },
    "keyTooltipExtendedBelowLine": {
      "sourceKey": "Spell_YunaraQ_TooltipExtendedBelowLine",
      "text": "<rules>散播攻击可以暴击并且施加@Spread_Onhit_Efficacy*100@%效能的<OnHit>%i:OnHit%攻击特效</OnHit>。来自散播攻击的伤害对低于<scaleHealth>@Calc_Minion_Execute_Threshold@生命值</scaleHealth>的小兵造成@Calc_Minion_Execute_Amp@伤害。</rules>"
    },
    "keyCost": {
      "sourceKey": "Spell_YunaraQ_Cost",
      "text": "@BaseCost@法力"
    },
    "keyCooldown": {
      "sourceKey": "Spell_YunaraQ_Cooldown",
      "text": "无冷却时间"
    }
  }
